module Client {
  import S = SequenceFacts
  import P = SequenceProperties
  lemma AppendKeepsNonempty(s: seq<int>, t: seq<int>)
    requires S.Size(s) > 0
    ensures P.Nonempty(s + t)
  {
  }
}

FILE SequenceFacts.dfy
module SequenceFacts {
  export provides Size, LengthConcat
  opaque function Size(s: seq<int>): nat { |s| }

  lemma LengthConcat(s: seq<int>, t: seq<int>)
    ensures Size(s + t) == Size(s) + Size(t)
  { reveal Size(); }
}

FILE SequenceProperties.dfy
include "SequenceFacts.dfy"
module SequenceProperties {
  import S = SequenceFacts
  export provides S, Nonempty, FromPositive
  opaque predicate Nonempty(s: seq<int>) { S.Size(s) > 0 }

  lemma FromPositive(s: seq<int>)
    requires S.Size(s) > 0
    ensures Nonempty(s)
  { reveal Nonempty(); }
}

